import fp from 'fastify-plugin'

// Fixed-window counter per key. Good enough for a per-tenant cap; swap the Map
// for Redis when the API runs on more than one instance.
export default fp(async (app) => {
  app.decorate('rateLimit', ({ max, windowMs, keyOf }) => {
    const hits = new Map()
    return async (req, reply) => {
      const k = keyOf(req)
      const now = Date.now()
      const cur = hits.get(k)
      if (!cur || cur.reset <= now) hits.set(k, { n: 1, reset: now + windowMs })
      else if (++cur.n > max) {
        reply.header('Retry-After', Math.ceil((cur.reset - now) / 1000))
        return reply.code(429).send({ error: 'rate limit exceeded' })
      }
    }
  })
})

