export async function archiveOrders(app, { months = 18 } = {}) {
  const { rowCount } = await app.db.query(
    `UPDATE orders SET archived_at = now() WHERE archived_at IS NULL AND created_at < now() - ($1 || ' months')::interval`,
    [months]
  )
  app.log.info({ archived: rowCount }, 'archived old orders')
  return rowCount
}

